  ]
}

parameters.jsCode:
// Parse Claude classification, compute deadline, prepare DB insert.
const llm = $input.first().json;
const inbox = $('Privacy Inbox Poll').item.json;
const text = llm.content?.[0]?.text || '';

let cls;
try {
  cls = JSON.parse(text.match(/\{[\s\S]*\}/)[0]);
} catch (e) {
  cls = { request_type: 'unclear', jurisdiction: 'unclear', subject_email: inbox.from, urgency_signal: 'medium', malicious_signal: 'medium' };
}

// Deadline math per jurisdiction.
const DEADLINE_DAYS = {
  'EU-GDPR': 30,
  'UK-GDPR': 30,
  'CCPA-CPRA': 45,
  'LGPD': 15,
  'VCDPA': 45,
  'CDPA': 45,
  'CPA': 45,
  'other': 30,  // conservative default
  'unclear': 30,
};
const days = DEADLINE_DAYS[cls.jurisdiction] || 30;
const now = new Date();
const deadline = new Date(now.getTime() + days * 86400 * 1000);

return [{
  json: {
    dsar_id: `dsar-${now.getTime()}-${Math.random().toString(36).slice(2, 8)}`,
    received_at: now.toISOString(),
    request_type: cls.request_type,
    jurisdiction: cls.jurisdiction,
    subject_email_claimed: cls.subject_email,
    sender_email: inbox.from,
    urgency_signal: cls.urgency_signal,
    malicious_signal: cls.malicious_signal,
    deadline: deadline.toISOString(),
    deadline_days: days,
    raw_subject: inbox.subject,
    raw_snippet: (inbox.snippet || '').slice(0, 1000),
    status: 'pending_verification',
  }
}];

parameters.text:
Hello,

We received a data-subject request from your email address (or from someone claiming to act on your behalf). To act on this request, applicable law requires us to verify your identity.

Reference: {{ $('Compute Deadline').item.json.dsar_id }}
Received: {{ $('Compute Deadline').item.json.received_at }}
Deadline for our response (assuming verification clears within 7 days): {{ $('Compute Deadline').item.json.deadline }}

To verify, please reply to this email with [jurisdiction-appropriate verification — e.g. for CCPA-CPRA: confirmation of three pieces of personal information we hold on you; for GDPR: a description of the data you are requesting access to and confirmation of your residency status]. See attached template for jurisdiction details.

If you did not make this request, please reply to this email with 'Not me' and we will close the request without taking action.

The firm's privacy team

